// P2 roofs: R-main (hip + pediment + dormers) is the CLI roof step in make.sh, after every part; R-turret is the cone
// over the octagonal bay, built here (plan.md Roofs, E12/E13). The keep boxes in make.sh (turret x1..8 y10..30 z6..11)
// stop the main re-roof from touching it.
import { roof } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/roofs.mjs";
import { TURRET } from "./vocab.mjs";

export function build(g) {
  // R-turret: slate cone from y12 over the turret footprint, at most 5 courses, lightning rod finial (E12).
  roof(g, [[TURRET.x0, TURRET.z0, TURRET.x1, TURRET.z1]], "cone", {
    y: 12, material: "slate", maxHeight: 5, finial: "lightning_rod", overhang: 1,
  });
}

