import * as roofs from "/Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/mcmansion-opus-medium/crew/part-2/parts/roofs.mjs";
const g = new Grid([44, 18, 32], { dataVersion: DATA_VERSIONS["26.3"] });
g.fill([0, 0, 0], [43, 0, 31], "grass_block");
shell.build(g);
const before = new Set();
for (let y = 10; y < 18; y++) for (let x = 0; x < 44; x++) for (let z = 0; z < 32; z++) { const b = g.blockAt(x, y, z); if (b && !/air/.test(b)) before.add(`${x},${y},${z}`); }
roofs.build(g);
const tops = {};
for (let y = 10; y < 18; y++) for (let x = 0; x < 44; x++) for (let z = 0; z < 32; z++) {
  if (before.has(`${x},${y},${z}`)) continue;
  const b = g.blockAt(x, y, z); if (b && !/air/.test(b)) { tops[y] = (tops[y] || 0) + 1; }
}
console.log("roof cells by y:", JSON.stringify(tops));
EOF
cd /tmp/p2check && node top.mjs 2>&1 | tail -5; date

